const byId=new Map(WPA_INSTITUTIONS.map(r=>[r.id,r]));
export function getWpaInstitution(id){return typeof id==='string'&&/^[ABCDGHIR]\d{3}$/.test(id)?byId.get(id)||null:null;}
export function institutionResearchGate(record){
 if(!record)return 'INSTITUTION_NOT_IN_REV7';
 if(record.role==='WPA_INTERNAL')return 'INTERNAL_WPA_NOT_EXTERNAL_SOURCE';
 if(record.role==='AUDIT_CHILD')return 'AUDIT_CHILD_RESOLVE_CANONICAL_PARENT';
 if(record.role==='OBSERVATION_NOT_INSTITUTION')return 'OBSERVATION_NOT_A_VERIFIED_INSTITUTION';
 if(record.role==='HISTORICAL')return 'HISTORICAL_NO_AUTOMATIC_CURRENT_IDENTITY';
 if(!record.website)return 'SOURCE_WEBSITE_UNRESOLVED';
 // Website and institutional verification do NOT establish scholarly affiliation.
 return 'OPENALEX_AFFILIATION_CANDIDATE_REQUIRES_INDEPENDENT_REVIEW';
}
export function filterWpaInstitutions(needle='',limit=15){
 const t=String(needle||'').normalize('NFKD').toLowerCase().trim().slice(0,100);
 if(!t)return WPA_INSTITUTIONS.filter(x=>x.role==='INSTITUTION_CANDIDATE').slice(0,limit);
 return WPA_INSTITUTIONS.filter(x=>(x.name+' '+x.country+' '+x.id).normalize('NFKD').toLowerCase().includes(t)).slice(0,limit);
}
export function verifyRev7Projection(master){
 const rows=master?.institutions,meta=master?.metadata;
 if(!Array.isArray(rows)||rows.length!==250||meta?.version!==WPA_REV7_VERSION||
   meta.total_records!==WPA_REV7_EXPECTED.records||
   meta.external_records!==WPA_REV7_EXPECTED.external||
   meta.records_with_website!==WPA_REV7_EXPECTED.records_with_websites||
   meta.unique_external_institutions!==WPA_REV7_EXPECTED.unique_external_methodological)
  return false;
 return rows.every((r,i)=>r.id===WPA_INSTITUTIONS[i].id&&r.name===WPA_INSTITUTIONS[i].name&&
   r.country===WPA_INSTITUTIONS[i].country&&
   (r.website||null)===WPA_INSTITUTIONS[i].website);
}
